```

6. Schließlich erstellen Sie eine neue Datei namens `cypress/cypress.dockerfile`:

```Dockerfile
FROM node:14-alpine

# Add Cypress to the image
COPY package*.json ./
RUN npm install

# Add Cypress plugins
COPY cypress/plugins/ ./
COPY cypress/support/ ./

# Add Cypress test files
COPY cypress/integration/ ./

# Set working directory
WORKDIR /cypress

# Expose Cypress server port
EXPOSE 8080

# Set environment variables
ENV NODE_ENV=development

# Copy test artifacts to the host machine
